INSERT INTO MISSION_CYCLES (
    user_id, cycle_start_date, cycle_end_date, status,
    source_analysis_result_id, prompt_version, generation_error, generated_at
) VALUES (
    #{userId}, #{cycleStartDate}, #{cycleEndDate}, #{status},
    #{sourceAnalysisResultId}, #{promptVersion}, #{generationError}, #{generatedAt}
)

INSERT INTO MISSIONS (
    mission_cycle_id, title, description, category, difficulty,
    reward_point, verification_type, verification_rule,
    evidence_guide, deduplication_key
) VALUES (
    #{missionCycleId}, #{title}, #{description}, #{category}, #{difficulty},
    #{rewardPoint}, #{verificationType}, #{verificationRuleJson},
    #{evidenceGuide}, #{deduplicationKey}
)

INSERT INTO DAILY_MISSIONS (
    mission_cycle_id, mission_id, user_id, assigned_date, display_order, status
) VALUES (
    #{missionCycleId}, #{missionId}, #{userId}, #{assignedDate}, #{displayOrder}, #{status}
)

mapper.update:
UPDATE DAILY_MISSIONS
SET status = #{status},
    completed_at = CASE WHEN #{status} = 'COMPLETED' THEN CURRENT_TIMESTAMP ELSE completed_at END
WHERE daily_mission_id = #{dailyMissionId}
  AND user_id = #{userId}

UPDATE DAILY_MISSIONS
SET status = 'EXPIRED'
WHERE user_id = #{userId}
  AND assigned_date < #{assignedDate}
  AND status = 'ASSIGNED'
